import os

print("Working directory:", os.getcwd())
for name in sorted(os.listdir(".")):
    path = os.path.join(".", name)
    if os.path.isfile(path):
        print(f"FILE {name} ({os.path.getsize(path)} bytes)")
    else:
        print(f"DIR  {name}")
